{
  "genre": ["生存", "沙盒", "合作多人"],
  "perspective": "第三人称俯视角，玩家可自由旋转和缩放摄像机；单人游玩与多人合作时视角一致",
  "game_overview": "《Don't Starve Together》（饥荒联机版）是加拿大开发商 Klei Entertainment 出品的独立生存沙盒游戏，是《Don't Starve》的独立多人扩展版本，于 2016 年 4 月 21 日正式发售。玩家扮演一名被投入随机生成的荒野世界的幸存者，在哥特式手绘美术风格的世界中采集资源、制作工具与建筑、烹饪食物，并应对昼夜循环、四季更替、饥饿、理智与体温等多重生存压力。游戏以合作多人（最多 6 人）为核心形态，也支持单人游玩；死亡并非永久——玩家会变为幽灵，可由队友或特定道具复活，但在默认的生存模式下若全体玩家死亡且未在时限内复活，世界将重置。区别于同类生存游戏的关键特征包括：独特的哥特暗黑美术与手绘动画风格、以理智值（Sanity）为核心的心理压力系统（低理智会引发幻觉与影怪）、随机生成且包含地表、洞穴、遗迹、月球岛屿等多层区域的世界、以及每个角色拥有截然不同专属能力与弱点的角色系统。游戏持续获得长线更新，不断加入新角色、新生物、新机制与季节事件。",
  "gameplay": {
    "player_goal": "玩家的核心目标是在一个随机生成、充满敌意的荒野世界中尽可能长久地生存下去：维持饥饿、理智与健康三项生存指标，抵御季节灾害与怪物袭击，逐步探索地图、解锁科技、建立基地，并最终挑战世界中的强大首领。在合作模式下，玩家还需与队友协作分工，共同建设与防御。",
    "core_loop": "1. 进入随机生成的世界，从出生点（Florid Postern）开始，先采集基础资源（树枝、草、燧石、木头、石头等）。2. 白天探索地图，寻找食物来源（浆果、胡萝卜、动物等），并收集制作工具所需的材料。3. 黄昏与夜晚来临前，准备光源（火把、营火或火坑），因为黑暗中会出现秒杀玩家的影怪。4. 制作科学机器（Science Machine）等原型机，解锁并制作更高级的工具、武器、衣物与建筑。5. 建立基地：建造火坑、冰箱、烹饪锅、晾肉架、农田等设施，形成可持续的食物与资源生产体系。6. 应对季节更替——冬季防寒、夏季防暑、春季防雨，并准备应对各季节出现的首领怪物。7. 深入洞穴、遗迹或航行至月球岛屿等更危险的区域，获取稀有资源与更强大的科技。8. 死亡后变为幽灵，等待队友复活或使用复活道具；若全体死亡且未复活，世界重置，重新开始。",
    "major_systems": [
      {
        "name": "生存指标系统（饥饿/理智/健康）",
        "description": "三项核心数值决定玩家能否存活。饥饿随时间持续下降，归零后持续扣血；理智在黑暗、靠近怪物、食用变质食物等情况下下降，低理智会引发幻觉并召唤影怪攻击；健康在受到攻击、饥饿或理智归零时下降，归零即死亡。三者相互关联，例如食用怪物肉可填饱饥饿但会降低理智。"
      },
      {
        "name": "季节与天气系统",
        "description": "一年分为秋季（20天）、冬季（15天）、春季（20天）、夏季（15天）四个季节。冬季会冻结、夏季会过热并引发野火、春季多雨导致潮湿与闪电。每个季节都有对应的首领怪物（秋季熊獾、冬季巨鹿、春季麋鹿鹅、夏季蚁狮），击败后掉落制作强力装备的材料。"
      },
      {
        "name": "制作与原型系统",
        "description": "游戏采用\"原型一次、随处制作\"的机制：站在科学机器、炼金引擎、暗影操纵者等原型机旁首次制作某物品即可永久解锁该配方，之后可在任何地点制作。原型机分为多个科技层级，从基础科学到魔法、远古科技、天体科技，逐层解锁更强大的物品。"
      },
      {
        "name": "角色系统",
        "description": "游戏提供超过 20 名可玩角色，每名角色拥有独特的专属能力、属性加成与弱点。例如 Wilson 的胡子可保暖、Wendy 可召唤姐妹 Abigail 协助战斗、WX-78 可通过齿轮提升属性但怕雨、Wickerbottom 可阅读魔法书但无法正常睡觉。角色选择直接影响玩家的策略与团队分工。"
      },
      {
        "name": "基地建设系统",
        "description": "玩家可建造火坑、冰箱、烹饪锅、晾肉架、农田、围墙、陷阱、避雷针等大量建筑与设施，形成可持续的生存基地。基地位置选择、布局规划与防御工事建设是长期生存的关键。"
      },
      {
        "name": "烹饪与食物系统",
        "description": "使用烹饪锅（Crock Pot）可将多种食材组合烹饪成具有不同效果的料理，部分料理可恢复理智或提供特殊增益。食物有保质期会变质，可通过冰箱、晾肉架等方式延长保存。不同角色对食物的偏好与效果也不同。"
      },
      {
        "name": "探索与多层世界系统",
        "description": "世界由多种生物群系（森林、草原、沼泽、沙漠、月球岛屿等）随机生成，并包含地表、洞穴、遗迹、月球区域等多层空间。玩家可深入地下探索远古遗迹，或建造船只航行至月球岛屿，获取稀有资源与高级科技。"
      },
      {
        "name": "战斗与怪物系统",
        "description": "世界中有大量敌对生物（猎犬、蜘蛛、青蛙、发条生物等）以及各季节的首领级怪物。玩家需制作武器、护甲、陷阱或利用环境来应对。部分生物可被驯服或成为盟友（如猪人、兔人、蜘蛛等）。"
      },
      {
        "name": "死亡与复活系统",
        "description": "死亡后玩家变为幽灵，可骚扰物品或等待复活。复活方式包括队友使用 Telltale Heart、触摸石、肉雕像、生命护符等。在生存模式下，全体死亡后开始 120 秒倒计时，无人复活则世界重置。复活会累积最大生命值惩罚。"
      },
      {
        "name": "世界模式（Playstyle）系统",
        "description": "创建世界时可选择五种模式：生存（默认，全体死亡后世界重置）、无尽（世界不重置，可无限复活）、荒野（死亡后重新选角色随机出生）、轻松（威胁减少，不会因饥饿/寒冷/黑暗死亡）、熄灯（永久黑夜）。不同模式改变死亡惩罚与游戏节奏。"
      }
    ],
    "modes_and_structure": "游戏以持续存在的沙盒世界为基本结构，没有传统意义上的关卡或回合。玩家创建或加入一个世界（最多 6 人合作），在同一个世界中持续生存、探索与建设。世界按天数推进，每 70 天为一个完整年度（四季循环）。主要模式为合作生存（默认），也支持可选的 PvP 设定（由服务器管理员决定）。此外还有限时活动模式（如 Forge 竞技场合作挑战、Gorge 烹饪合作挑战），以及五种可自定义的世界模式（生存、无尽、荒野、轻松、熄灯）供玩家选择。单人游玩时同样使用相同的世界结构，只是没有其他玩家。",
  "background": {
    "setting_and_premise": "游戏设定在一个名为\"永恒领域\"（The Constant）的哥特式暗黑荒野世界中。玩家扮演被神秘力量（马克斯韦尔）召唤或困入此世界的幸存者，需要在这个充满怪异生物、超自然现象与严酷自然环境的异世界中挣扎求生。世界包含地表、洞穴、遗迹与月球区域等多层空间，隐藏着古老的秘密与强大的存在。游戏的美术风格为手绘哥特式卡通，整体氛围黑暗、诡异但带有黑色幽默。玩家不需要了解完整剧情即可游玩，核心体验是生存、探索与建设。",
    "release_and_service_status": "游戏于 2014 年 12 月 15 日进入 Steam 抢先体验（Early Access），2016 年 4 月 21 日正式发售。游戏持续获得长线运营更新，包括定期推出的新角色、新生物、新机制与季节活动（如\"From Beyond\"系列更新、角色技能树系统等）。截至 2024-2025 年，游戏仍在持续更新中，具体最新版本状态建议以官方公告为准。"
  },
  "default_pc_keybinds": [
    {"action": "移动（前进/左/后退/右）", "input": "W / A / S / D"},
    {"action": "自动行动（拾取、互动，不攻击）", "input": "空格键（Space）"},
    {"action": "自动攻击", "input": "F"},
    {"action": "强制攻击中立生物", "input": "Ctrl + F"},
    {"action": "强制攻击友方生物", "input": "Alt + F"},
    {"action": "检查/调查物品", "input": "Alt + 左键点击"},
    {"action": "打开地图", "input": "Tab"},
    {"action": "打开制作菜单", "input": "C"},
    {"action": "旋转摄像机（逆时针/顺时针）", "input": "Q / E"},
    {"action": "缩放摄像机", "input": "鼠标滚轮"},
    {"action": "使用快捷栏物品（第1-10格）", "input": "数字键 1-0"},
    {"action": "打开暂停菜单", "input": "Esc"},
    {"action": "全局聊天", "input": "Y"},
    {"action": "附近（耳语）聊天", "input": "U"},
    {"action": "打开控制台", "input": "~（波浪号）"}
  ]
}
